import numpy as np, itertools
def read_xyz(p):
    lines=open(p).read().splitlines()
    n=int(lines[0]); ats=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); ats.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return ats, np.array(xyz)
ats, xyz = read_xyz('opt1.xyz')
n=len(ats)
cov={'H':0.31,'C':0.76,'N':0.71,'Ni':1.24}
bonds=[]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d < cov[ats[i]]+cov[ats[j]]+0.45:
        bonds.append((i,j,round(d,2)))
# heavy atom bonds
for i,j,d in bonds:
    if ats[i]!='H' and ats[j]!='H':
        print(f"{i}{ats[i]}-{j}{ats[j]} {d}")
print()
ni=1
for i,j,d in bonds:
    if ni in (i,j):
        print("Ni bond:", i, ats[i], j, ats[j], d)
# check N substituents
for N in [2,6,11,15]:
    nb=[(i if j==N else j) for i,j,d in bonds if N in (i,j)]
    print("N",N,"neighbors:",[(x,ats[x]) for x in nb])
